arguments.command:
cd /tmp/sv-4a53cbd27a89491680a9774901da0542 && \
# The binary is stripped but might have dynamic symbols. Let's check for symbols near the PCs.
# Frame offsets for libmonosgen-2.0.so: 0x222098, 0x222234, 0x19bac0, 0x19bc14
# We need an aarch64 cross-toolchain for addr2line since this is arm64
# Let's try using readelf to find dynamic symbols near those addresses
readelf -W --dyn-syms symbols/libmonosgen-2.0.so 2>/dev/null | head -5
echo "---"
# Count dynamic symbols
readelf -W --dyn-syms symbols/libmonosgen-2.0.so 2>/dev/null | wc -l
echo "---"
# Check if we can find symbols containing the target addresses
# Addresses: 0x222098, 0x222234, 0x19bac0, 0x19bc14
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo "=== Looking for symbol near $addr ==="
  # Find the closest symbol at or before this address
  readelf -W --dyn-syms symbols/libmonosgen-2.0.so 2>/dev/null | \
    awk -v target="$addr" '
    BEGIN { target_dec = strtonum(target); best_name=""; best_addr=0; best_size=0 }
    /FUNC/ {
      addr = strtonum("0x" $2);
      size = strtonum($3);
      if (addr <= target_dec && addr > best_addr) {
        best_addr = addr;
        best_size = size;
        best_name = $8;
      }
    }
    END {
      if (best_name != "") {
        offset = target_dec - best_addr;
        printf "  %s+0x%x (sym at 0x%x, size %d)\n", best_name, offset, best_addr, best_size;
      } else {
        print "  (no symbol found)";
      }
    }'
done

