arguments.command:
cd /tmp/sv-4a53cbd27a89491680a9774901da0542 && \
# Get all dynamic symbols sorted by address, then for each target find the nearest
readelf -W --dyn-syms symbols/libmonosgen-2.0.so 2>/dev/null | \
  awk '/FUNC|OBJECT/ && $2 != "0000000000000000" { printf "0x%s %s %s\n", $2, $3, $8 }' | \
  sort -k1,1 > /tmp/mono_syms.txt

for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo "=== $addr ==="
  addr_dec=$((addr))
  # Find closest symbol before this address
  awk -v target="$addr_dec" '
  {
    a = strtonum($1);
    if (a <= target) { last_addr=a; last_size=$2; last_name=$3; }
  }
  END {
    if (last_name != "") {
      offset = target - last_addr;
      printf "  %s+0x%x\n", last_name, offset;
    }
  }' /tmp/mono_syms.txt
done

